compile.workshop:
variables {
    global:
        0: value
}

rule ("issue 33 switch break") {
    event {
        Ongoing - Global;
    }
    actions {
        If(True);
            Skip(Value In Array(Array(3, 0, 1), Add(1, Index Of Array Value(Array(1, 2), Global.value))));
        //__label_switch_2_0__:
        Set Global Variable(value, 2);
        //__label_switch_2_1__:
        Set Global Variable(value, 3);
        Else;
        //__label_switch_2_default__:
        Set Global Variable(value, 4);
        End;
        While(Compare(Global.value, <, 10));
            If(True);
                Skip(Value In Array(Array(1, 0), Add(1, Index Of Array Value(Array(3), Global.value))));
            //__label_switch_3_0__:
            Else;
            //__label_switch_3_default__:
            Else;
            End;
            Break;
        End;
    }
}

